contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint setMinSum, uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.SetMinSum(setMinSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEthBefore = address(c).balance;

        bool ok;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEthAfter = address(c).balance;

        assert(ok || (balAfter == balBefore && cEthAfter == cEthBefore));
    }

    receive() external payable {}
}

